def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    cindy_bid = None
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev['bid'])
                if agent_id == 'Cindy':
                    cindy_bid = prev['bid']

    if not alive:
        return max(0.0, min(budget, 18.0))

    alive_count = len(alive)
    scarcity = supply / float(WATER_REQ * (alive_count + 1))
    severe_need = hp <= 3 or no_water >= 2
    moderate_need = hp <= 5 or no_water >= 1

    pressure = max(prev_bids) if prev_bids else 0.0
    if cindy_bid is None:
        cindy_bid = pressure

    if severe_need:
        if supply <= 16:
            target = max(90.0, cindy_bid + 2.0)
        elif supply <= 19:
            target = max(78.0, cindy_bid * 0.82)
        else:
            target = 62.0
    elif moderate_need:
        if supply <= 16:
            target = max(74.0, cindy_bid * 0.72)
        elif supply <= 19:
            target = max(56.0, min(72.0, pressure + 2.0))
        else:
            target = 42.0
    else:
        if scarcity < 0.7:
            target = 52.0 if supply <= 17 else 36.0
        elif scarcity < 0.9:
            target = 28.0
        else:
            target = 16.0

    days_left = max(1, 10 - day + 1)
    reserve_floor = 22.0 * days_left
    if budget < reserve_floor:
        target = min(target, max(10.0, budget / float(days_left)))

    if day >= 8 and hp > 5 and no_water == 0:
        target *= 0.9

    bid = max(0.0, min(budget, target))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents alive, bid to secure our requirement cheaply
    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive_opps:
        pt = o.get('previous_trace', {}) or {}
        bid = pt.get('bid', None)
        if bid is not None:
            prev_bids.append(float(bid))
            prev_hp_after.append(pt.get('hp_after', o.get('hp', 0)))

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    # Estimate how many water units are likely contested
    # Use supply bins to decide whether we can undercut or must match pressure.
    # int() to avoid float index issues (even though we won't index lists here).
    supply_int = int(supply)
    shortage = supply_int < (MIN_SUPPLY + MAX_SUPPLY) / 2  # below mid-range

    my_hp = my_status.get('hp', 0)
    my_budget = my_status.get('budget', 0.0)
    my_no_water_days = my_status.get('no_water_days', 0)

    # Pressure heuristic from yesterday: if someone bid near/above salary threshold, they likely fought for survival.
    pressure = 0.0
    if highest_prev_bid >= 0.85 * DAILY_SALARY:
        pressure = 1.0
    elif highest_prev_bid >= 0.6 * DAILY_SALARY:
        pressure = 0.7
    elif highest_prev_bid >= 0.3 * DAILY_SALARY:
        pressure = 0.4
    else:
        pressure = 0.25

    # If my HP is critical, I must bid higher regardless of supply.
    if my_hp <= 2 or my_no_water_days >= 2:
        base = DAILY_SALARY * (0.75 if not shortage else 0.95)
    elif shortage:
        base = DAILY_SALARY * (0.55 + 0.25 * pressure)
    else:
        base = DAILY_SALARY * (0.45 + 0.25 * pressure)

    # Undercut logic: try to bid slightly above the previous highest when pressure is high,
    # otherwise keep it around our base but not too high.
    if pressure >= 0.7:
        target = max(base, min(my_budget, highest_prev_bid + 2.0))
    else:
        target = max(base, min(my_budget, avg_prev_bid * 0.95 + 2.0)) if avg_prev_bid > 0 else base

    # Ensure we never exceed budget and never go negative
    bid = max(0.0, min(float(my_budget), float(target)))

    # Small day-based adjustment: later days require stronger bids to avoid running out.
    # episode_days is fixed at 10 in meta-round; use day to ramp.
    # day_context['day'] is assumed 1..10.
    if day is not None:
        try:
            d = int(day)
        except Exception:
            d = 1
        if d >= 8:
            bid = min(float(my_budget), bid * 1.12)
        elif d <= 2:
            bid = bid * 0.92

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    budget = my_status['budget']
    hp = my_status['hp']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, 20.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    max_prev = max(prev_bids) if prev_bids else 70.0

    if hp <= 3:
        return min(budget, max_prev * 1.2, DAILY_SALARY * 1.1)

    if supply < 18:
        return min(budget, max(max_prev * 1.05, 75.0))

    return min(budget, max(60.0, max_prev * 0.95))
